CREATE SCHEMA IF NOT EXISTS dbo;
CREATE TABLE dbo.Users (UserID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,LoginName varchar(100) UNIQUE NOT NULL,PasswordHash varchar(255) NOT NULL,DisplayName nvarchar(180) NOT NULL,IsActive bit DEFAULT 1 NOT NULL,CreatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE dbo.Roles (RoleID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,RoleCode varchar(40) UNIQUE NOT NULL,Name nvarchar(180) NOT NULL);
CREATE TABLE dbo.Permissions (PermissionID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,PermissionCode varchar(40) UNIQUE NOT NULL,Name nvarchar(180) NOT NULL);
CREATE TABLE dbo.UserRoles (UserID bigint REFERENCES dbo.Users,RoleID bigint REFERENCES dbo.Roles,PRIMARY KEY(UserID,RoleID));
CREATE TABLE dbo.RolePermissions (RoleID bigint REFERENCES dbo.Roles,PermissionID bigint REFERENCES dbo.Permissions,PRIMARY KEY(RoleID,PermissionID));
CREATE TABLE dbo.Customers (CustomerID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,CustomerCode varchar(40) UNIQUE NOT NULL,FullName nvarchar(180) NOT NULL,Phone varchar(25) NOT NULL,Email varchar(254),UserID bigint REFERENCES dbo.Users,CreatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE dbo.CustomerAddresses (AddressID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,CustomerID bigint REFERENCES dbo.Customers,RecipientName nvarchar(180) NOT NULL,RecipientPhone varchar(25) NOT NULL,AddressLine nvarchar(250) NOT NULL,WardText nvarchar(120) NOT NULL,ProvinceText nvarchar(120) NOT NULL,IsDefault bit NOT NULL);
-- H2 tương đương phần schema Tuần 10; SQL Server chạy migration thật qua test opt-in.
CREATE TABLE dbo.Categories (CategoryID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,CategoryCode varchar(40) NOT NULL,Name nvarchar(180) NOT NULL,IsActive bit DEFAULT 1 NOT NULL,Revision int DEFAULT 0 NOT NULL,CodeKey varchar(40) GENERATED ALWAYS AS (UPPER(TRIM(CategoryCode))) UNIQUE);
CREATE TABLE dbo.Brands (BrandID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,BrandCode varchar(40) NOT NULL,Name nvarchar(180) NOT NULL,IsActive bit DEFAULT 1 NOT NULL,Revision int DEFAULT 0 NOT NULL,CodeKey varchar(40) GENERATED ALWAYS AS (UPPER(TRIM(BrandCode))) UNIQUE);
CREATE TABLE dbo.Units (UnitID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,UnitCode varchar(40) NOT NULL,Name nvarchar(180) NOT NULL,IsActive bit DEFAULT 1 NOT NULL,Revision int DEFAULT 0 NOT NULL,CodeKey varchar(40) GENERATED ALWAYS AS (UPPER(TRIM(UnitCode))) UNIQUE);
CREATE TABLE dbo.Products (ProductID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,SKU varchar(40) NOT NULL,Name nvarchar(180) NOT NULL CHECK(LENGTH(TRIM(Name))>0),CategoryID bigint NOT NULL REFERENCES dbo.Categories,BrandID bigint REFERENCES dbo.Brands,UnitID bigint NOT NULL REFERENCES dbo.Units,StockMode varchar(24) NOT NULL CHECK(StockMode IN ('BULK','SERIALIZED')),ListPrice decimal(19,2) NOT NULL CHECK(ListPrice>=0),Description nvarchar(2000),IsActive bit DEFAULT 1 NOT NULL,IsPublished bit DEFAULT 0 NOT NULL,Revision int DEFAULT 0 NOT NULL,CreatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,UpdatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,SKUKey varchar(40) GENERATED ALWAYS AS (UPPER(TRIM(SKU))) UNIQUE);
CREATE TABLE dbo.ProductImages (ImageID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ProductID bigint NOT NULL REFERENCES dbo.Products,ImageURL nvarchar(600) NOT NULL,SortOrder int NOT NULL);
CREATE TABLE dbo.AttributeDefinitions (AttributeID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,AttributeCode varchar(40) UNIQUE NOT NULL,Name nvarchar(180) NOT NULL,UnitLabel nvarchar(30),ValueType varchar(24) NOT NULL CHECK(ValueType IN ('TEXT','INTEGER','DECIMAL','BOOLEAN')));
CREATE TABLE dbo.ProductAttributeValues (ProductID bigint NOT NULL REFERENCES dbo.Products,AttributeID bigint NOT NULL REFERENCES dbo.AttributeDefinitions,ValueText nvarchar(250) NOT NULL,PRIMARY KEY(ProductID,AttributeID));
CREATE TABLE dbo.Devices (DeviceID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,AssetTag varchar(40) NOT NULL,ProductID bigint REFERENCES dbo.Products,OwnerCustomerID bigint REFERENCES dbo.Customers,ManufacturerSerial nvarchar(100),DeviceDescription nvarchar(2000) NOT NULL,ConditionGrade varchar(24) DEFAULT 'GOOD' NOT NULL CHECK(ConditionGrade IN ('NEW','LIKE_NEW','GOOD','FAIR','FAULTY')),AskingPrice decimal(19,2) CHECK(AskingPrice>=0),FaultDescription nvarchar(2000),IsPublished bit DEFAULT 0 NOT NULL,Version varbinary(8) DEFAULT X'0000000000000000' NOT NULL,CreatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,UpdatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,AssetTagKey varchar(40) GENERATED ALWAYS AS (UPPER(TRIM(AssetTag))) UNIQUE);
CREATE TRIGGER Devices_RowVersion BEFORE INSERT,UPDATE ON dbo.Devices FOR EACH ROW CALL 'com.tivarek.week11.H2RowVersionTrigger';
CREATE TABLE dbo.DeviceAttributeValues (DeviceID bigint REFERENCES dbo.Devices,AttributeID bigint REFERENCES dbo.AttributeDefinitions,ValueText nvarchar(250) NOT NULL,PRIMARY KEY(DeviceID,AttributeID));
CREATE TABLE dbo.DeviceImages (ImageID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,DeviceID bigint NOT NULL REFERENCES dbo.Devices,ImageURL nvarchar(600) NOT NULL,SortOrder int NOT NULL CHECK(SortOrder>=0),UNIQUE(DeviceID,SortOrder));
CREATE TABLE dbo.DeviceChecks (CheckID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,DeviceID bigint NOT NULL REFERENCES dbo.Devices,CheckedBy bigint NOT NULL REFERENCES dbo.Users,CheckedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,Findings nvarchar(2000) NOT NULL,Result varchar(24) NOT NULL CHECK(Result IN ('PASS','FAIL','NEEDS_REPAIR')));
CREATE TABLE dbo.StockLocations (LocationID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,LocationCode varchar(40) NOT NULL,Name nvarchar(180) NOT NULL,LocationType varchar(24) NOT NULL,IsActive bit DEFAULT 1 NOT NULL);
CREATE TABLE dbo.InventoryDocuments (InventoryDocID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,DocumentCode varchar(40) NOT NULL,DocumentType varchar(24) NOT NULL,Status varchar(24) NOT NULL,OccurredAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE dbo.BulkStockEntries (BulkEntryID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,InventoryDocID bigint REFERENCES dbo.InventoryDocuments,ProductID bigint REFERENCES dbo.Products,LocationID bigint DEFAULT 1 NOT NULL,Delta int NOT NULL,UnitCost decimal(19,2) NOT NULL);
CREATE TABLE dbo.DeviceStockEntries (DeviceEntryID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,InventoryDocID bigint REFERENCES dbo.InventoryDocuments,DeviceID bigint REFERENCES dbo.Devices,FromLocationID bigint,ToLocationID bigint,UnitCost decimal(19,2) NOT NULL);
CREATE TABLE dbo.BulkSaleLines (SaleLineID bigint PRIMARY KEY,ProductID bigint REFERENCES dbo.Products,Quantity int NOT NULL);
CREATE TABLE dbo.BulkReservations (ReservationID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,SaleLineID bigint NOT NULL REFERENCES dbo.BulkSaleLines,LocationID bigint NOT NULL,Quantity int NOT NULL,Status varchar(24) NOT NULL,ExpiresAt timestamp NOT NULL,CreatedAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE dbo.ActiveDeviceReservations (DeviceID bigint PRIMARY KEY REFERENCES dbo.Devices,ReservationID bigint NOT NULL UNIQUE);
CREATE TABLE dbo.AuditLogs (AuditID bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ActorID bigint REFERENCES dbo.Users,Action varchar(60) NOT NULL,EntityType varchar(60) NOT NULL,EntityKey varchar(100) NOT NULL,Summary nvarchar(2000) NOT NULL,OccurredAt timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL);
